/*Table structure for table `storechange` */

DROP TABLE IF EXISTS `storechange`;

/*!50001 DROP VIEW IF EXISTS `storechange` */;
/*!50001 DROP TABLE IF EXISTS `storechange` */;

/*!50001 CREATE TABLE  `storechange`(
 `PNo` varchar(20) ,
 `PType` varchar(20) ,
 `PName` varchar(50) ,
 `PManufacturer` varchar(50) ,
 `PSize` varchar(50) ,
 `PUnit` varchar(20) ,
 `PCount` double ,
 `CTime` datetime 
)*/;

/*View structure for view storechange */

/*!50001 DROP TABLE IF EXISTS `storechange` */;
/*!50001 DROP VIEW IF EXISTS `storechange` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `storechange` AS select `f`.`PNo` AS `PNo`,`f`.`PType` AS `PType`,`f`.`PName` AS `PName`,`f`.`PManufacturer` AS `PManufacturer`,`f`.`PSize` AS `PSize`,`f`.`PUnit` AS `PUnit`,`f`.`PCount` AS `PCount`,`f`.`CTime` AS `CTime` from (select `i`.`PNo` AS `PNo`,`i`.`PType` AS `PType`,`i`.`PName` AS `PName`,`i`.`PManufacturer` AS `PManufacturer`,`i`.`PSize` AS `PSize`,`i`.`PUnit` AS `PUnit`,`i`.`InCount` AS `PCount`,`i`.`CTime` AS `CTime` from `w_instore` `i` union all select `o`.`PNo` AS `PNo`,`o`.`PType` AS `PType`,`o`.`PName` AS `PName`,`o`.`PManufacturer` AS `PManufacturer`,`o`.`PSize` AS `PSize`,`o`.`PUnit` AS `PUnit`,-(`o`.`POutCount`) AS `PCount`,`o`.`CTime` AS `CTime` from `w_outstore` `o`) `f` order by `f`.`CTime` desc */;

